			dw kw_out, lit_4667, lit_2
			dw p_vox_screen_r

; ============================================================
; function page (turbo mode)
; ============================================================

p_vox_page:

			; Vox.cls 51: Page = 32 + 6 * bufNo
			dw kw_mulvl, var_vox_bufno, 6, tmp6
			dw kw_addl, tmp6, 32, var_vox_page_page
			dw p_vox_page_r

; ============================================================
; sub flip (turbo mode)
; ============================================================

p_vox_flip:

			; Vox.cls 56: Nx.Reg &H12, 16 + 3 * bufNo
			dw kw_mulvl, var_vox_bufno, 3, tmp2
			dw kw_addl, tmp2, 16, tmp1
			dw fn_nx_reg, lit_18, tmp1

			; Vox.cls 57: bufNo = 1 - bufNo
			dw kw_sublv, 1, var_vox_bufno, var_vox_bufno
			dw p_vox_flip_r

