;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

do1_t_go:			ld sp, do1_t
			ret

p_vox_screen_c:		; call screen (turbo)
			pop hl			; colour
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_vox_screen_colour), de
			ld (p_vox_screen_rs), sp
			ld sp, p_vox_screen
			ret
p_vox_screen_r:		; end of screen
			ld sp, (p_vox_screen_rs)
			ret
p_vox_page_c:		; call page (turbo)
			ld hl, 0
			ld (var_vox_page_page), hl
			ld (p_vox_page_rs), sp
			ld sp, p_vox_page
			ret
p_vox_page_r:		; end of page
			ld sp, (p_vox_page_rs)
			ret
p_vox_flip_c:		; call flip (turbo)
			ld (p_vox_flip_rs), sp
			ld sp, p_vox_flip
			ret
p_vox_flip_r:		; end of flip
			ld sp, (p_vox_flip_rs)
			ret

