            inc hl		; Keys.cls 80
            ld d, (hl)		; Keys.cls 81
            ld a, d		; Keys.cls 82
            or a		; Keys.cls 83
            jr nz, fn_keys_down_kdno		; Keys.cls 84
            ld a, e		; Keys.cls 85
            cp 64		; Keys.cls 86
            jr nc, fn_keys_down_kdno		; Keys.cls 87
            and 7		; Keys.cls 88
            cp 5		; Keys.cls 89
            jr nc, fn_keys_down_kdno		; Keys.cls 90
            inc a		; Keys.cls 91
            ld d, a                 ; D = bit + 1 [92]
            ld a, e		; Keys.cls 93
            rrca		; Keys.cls 94
            rrca		; Keys.cls 95
            rrca		; Keys.cls 96
            and 7		; Keys.cls 97
            inc a                   ; A = half row + 1 [98]
            ld b, a		; Keys.cls 99
            ld a, #7F		; Keys.cls 100
fn_keys_down_kdrow:		; Keys.cls 101
            rlca                    ; #FE for half row 0, #FD 1 ... #7F 7 [102]
            djnz fn_keys_down_kdrow		; Keys.cls 103
            ld b, a		; Keys.cls 104
            ld c, #FE		; Keys.cls 105
            in a, (c)		; Keys.cls 106
            ld b, d		; Keys.cls 107
