            jr c, fn_keys_down_kdset               ; 1 = not pressed [112]
            dec de		; Keys.cls 113
            jr fn_keys_down_kdset		; Keys.cls 114
fn_keys_down_kdno:		; Keys.cls 115
            ld de, 0		; Keys.cls 116
fn_keys_down_kdset:		; Keys.cls 117
            pop hl		; Keys.cls 118
            ld (hl), e		; Keys.cls 119
            inc hl		; Keys.cls 120
            ld (hl), d		; Keys.cls 121
